import Link from 'next/link';
import { getPublishedPosts, categories, formatDate } from '@/lib/posts';

export default async function ResourcesPage() {
  const posts = await getPublishedPosts();

  return (
    <div className="resource-page">
      <div className="container">
        <p className="eyebrow">Resources</p>
        <h1 style={{ fontSize: 'clamp(2.5rem, 5vw, 4.4rem)', marginTop: 16, marginBottom: 18 }}>Knowledge, stories and product information.</h1>
        <div className="resource-filters" aria-label="Resource filters">
          <span className="filter-chip active">All</span>
          {categories.map((category) => (
            <span key={category} className="filter-chip">{category}</span>
          ))}
        </div>

        <div className="resources-grid">
          {posts.map((post) => (
            <Link key={post.id} href={`/resources/${post.slug}`} target="_blank" rel="noreferrer" className="resource-card">
              <div>
                <div className="resource-date">{post.category} · {formatDate(post.published_at)}</div>
                <h3>{post.title}</h3>
                <p style={{ color: '#5d6763', marginBottom: 18 }}>{post.excerpt}</p>
              </div>
              <span>Read article ↗</span>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}
